 $('#content').innerHTML=title(name,sub)+`<div class="toolbar"><input id="search" placeholder="搜索名称、公司或内容" value="${E(state.query)}">${state.page==='resumes'?button('新建','navigate','data-page="templates"',true)+button('从 PDF 导入','importResumePdf'):state.page==='interviews'?button('导入文档','importDocument','',true):state.page==='exams'?button('导入笔试题文件','importExamDocument','',true):button('新增','new',`data-kind="${state.page}"`,true)}</div>`+(state.page==='applications'?`<select id="list-filter">${options([['all','全部状态'],...['已打开','已投递','笔试中','面试中','已录用','已结束']],state.filter)}</select>`:state.page==='schedule'?`<select id="list-filter">${options([['all','全部日程'],['pending','待完成'],['completed','已完成']],state.filter)}</select>`:'')+(['favorites','applications'].includes(state.page)?button('标签／批量管理','workspace',`data-kind="${state.page}"`):'')+'<div id="list-items"></div><div id="pagination" class="actions"></div>';
