 preview:async d=>preview(d.id),togglePreviewPhoto:async()=>{state.previewPhoto=!state.previewPhoto;await renderPreview();},
  returnPreview:async()=>state.current&&['resumes','applications'].includes(state.kind)?runPageTransition(()=>renderEditor(),'back'):navigate(state.page),
 examplePreview:async()=>{state.previewSample=!state.previewSample;await renderPreview();},print:async()=>api('print',{title:state.previewDoc.title,html:await resumeHtml(state.previewDoc,false,state.previewPhoto)}),
